"""Hidden verifier: the orders DB master password is generated by Terraform and never persisted.

The stack is applied with `terraform test` against the local emulator, with no variables supplied
(CI no longer passes the password). The DB instance is replaced by an override because the provider
waits at least a minute before polling a new instance, which a verifier cannot afford; everything
else (the secret, its version, ephemeral resources, IAM) really runs. The emulator records what is
written to Secrets Manager, so the verifier knows the generated password and checks:
- the app's secret has the JSON the service reads, with that password;
- the password is a valid RDS PostgreSQL master password;
- the password appears nowhere in the state Terraform would persist, and no attribute that Terraform
  stores (password, secret_string, a generator's result) holds it.
"""

import json
import shutil
import unittest

import tfverify as tv

SECRET_NAME = 'orders/db'
DB_HOST = 'orders-prod.cvrfy0example.eu-west-1.rds.amazonaws.com'
TEST_DIR = 'zz_verify_tests'
RDS_FORBIDDEN = set('/"@')  # CreateDBInstance MasterUserPassword constraints
RANDOM_DEFAULT_SPECIAL = '!@#$%&*()-_=+[]{}<>:?'
GENERATORS = ('random_password', 'aws_secretsmanager_random_password', 'random_bytes')


def override_block(address, managed_secret_arn=None):
    # RDS-managed passwords are emulated with a secret shaped like the one RDS creates, so that
    # configurations using them still apply and are judged on what they do.
    managed = (
        f'    master_user_secret = [{{ secret_arn = "{managed_secret_arn}", secret_status = "active", '
        f'kms_key_id = "" }}]\n'
        if managed_secret_arn else ''
    )
    return f'''
override_resource {{
  target = {address}
  values = {{
    address        = "{DB_HOST}"
    endpoint       = "{DB_HOST}:5432"
    port           = 5432
    arn            = "arn:aws:rds:{tv.REGION}:{tv.ACCOUNT}:db:orders-prod"
    id             = "db-VERIFY0000000000000000000"
    resource_id    = "db-VERIFY0000000000000000000"
    hosted_zone_id = "Z29XKXDKYMONMX"
{managed}  }}
}}
'''


class OrdersDbPassword(unittest.TestCase):
    @classmethod
    def setUpClass(cls):
        cls.blocks = tv.parse_dir(tv.ROOT)
        cls.db_blocks = tv.resources(cls.blocks, 'resource', 'aws_db_instance')
        cls.emu = tv.Emulator()
        tv.clean_workspace()
        tv.write_override(cls.emu, cls.blocks)
        init = tv.init_if_needed(cls.blocks)
        if init is not None and init.returncode != 0:
            raise AssertionError(f'terraform init failed:\n{init.stdout[-2000:]}{init.stderr[-2000:]}')
        test_dir = tv.ROOT / TEST_DIR
        shutil.rmtree(test_dir, ignore_errors=True)
        test_dir.mkdir()
        managed_arn = None
        if any(tv.literal(b.attrs.get('manage_master_user_password')) is not False
               and 'manage_master_user_password' in b.attrs for b in cls.db_blocks):
            created = cls.emu.client('secretsmanager').create_secret(
                Name='rds!db-0verify0-0000-0000-0000-000000000000',
                SecretString=json.dumps({'username': 'orders_admin',
                                         'password': 'Rds-Managed-Verify-Password-0001'}),
            )
            managed_arn = created['ARN']
        overrides = ''.join(override_block(b.address, managed_arn) for b in cls.db_blocks)
        (test_dir / 'verify.tftest.hcl').write_text(
            overrides + '\nrun "apply" {\n  command = apply\n}\n', encoding='utf-8'
        )
        r = tv.tf('test', f'-test-directory={TEST_DIR}', '-json', '-verbose', '-no-color',
                  timeout=55)
        cls.raw = r.stdout + r.stderr
        cls.messages = tv.json_lines(r.stdout)
        cls.run_status = None
        cls.state = None
        for m in cls.messages:
            run = m.get('test_run')
            if run and run.get('run') == 'apply' and run.get('progress') == 'complete':
                cls.run_status = run.get('status')
            if 'test_state' in m:
                cls.state = m['test_state']
        cls.resources = tv.json_state_resources((cls.state or {}).get('root_module', {}))
        writes = [w for w in cls.emu.secret_writes
                  if w.get('secret_string') and SECRET_NAME in (str(w.get('name')), str(w.get('id')))]
        cls.secret_value = writes[-1]['secret_string'] if writes else None

    @classmethod
    def tearDownClass(cls):
        cls.emu.stop()

    # -- helpers ---------------------------------------------------------------------------------

    def require_apply(self):
        if not self.db_blocks:
            self.fail('no aws_db_instance resource found in the configuration')
        if self.run_status != 'pass' or self.state is None:
            hint = ''
            for m in self.messages:
                d = m.get('diagnostic') or {}
                if d.get('summary', '').startswith('No value for required variable'):
                    hint = (' (the configuration still requires an input variable, but CI will no '
                            'longer pass anything for the password)')
            errors = tv.describe_errors(self.messages, self.raw)
            self.fail(f'applying the stack without any input variables failed{hint}:\n{errors}')

    def of_type(self, rtype, mode='managed'):
        return [r for r in self.resources if r.get('type') == rtype and r.get('mode') == mode]

    def password(self):
        self.require_apply()
        if not self.secret_value:
            self.fail(f'nothing was written to the {SECRET_NAME} secret')
        try:
            data = json.loads(self.secret_value)
        except json.JSONDecodeError:
            self.fail(f'{SECRET_NAME} is not JSON')
        pw = data.get('password')
        if not isinstance(pw, str) or not pw:
            self.fail(f'{SECRET_NAME} has no password')
        return data, pw

    # -- tests -----------------------------------------------------------------------------------

    def test_applies_without_any_input(self):
        self.require_apply()

    def test_db_password_not_stored_by_the_instance(self):
        self.require_apply()
        dbs = self.of_type('aws_db_instance')
        self.assertTrue(dbs, 'no aws_db_instance in the applied state')
        for db in dbs:
            values = db.get('values', {})
            self.assertIn(values.get('password'), (None, ''),
                          f'{db["address"]}.password is set, and that argument is stored in state')

    def test_db_receives_a_terraform_generated_password(self):
        self.require_apply()
        for db in self.of_type('aws_db_instance'):
            values = db.get('values', {})
            self.assertFalse(
                values.get('manage_master_user_password'),
                'RDS-managed master passwords rotate automatically (every 7 days by default), which '
                f'the service cannot handle; it reads {SECRET_NAME} only at startup',
            )
            self.assertIsNotNone(
                values.get('password_wo_version'),
                f'{db["address"]} never receives the generated password (no password_wo / '
                'password_wo_version)',
            )

    def test_no_secret_material_in_stored_resources(self):
        self.require_apply()
        stored = [r['address'] for t in ('random_password', 'random_string')
                  for r in self.of_type(t)]
        self.assertFalse(stored, f'{stored} keep their generated result in the state file')
        reads = [r['address'] for t in ('aws_secretsmanager_secret_version',
                                         'aws_secretsmanager_random_password')
                 for r in self.of_type(t, 'data')]
        self.assertFalse(reads, f'data sources {reads} store the secret they read in the state file')

    def test_app_secret_kept_and_written_write_only(self):
        self.require_apply()
        secrets = [r for r in self.of_type('aws_secretsmanager_secret')
                   if r.get('values', {}).get('name') == SECRET_NAME]
        self.assertTrue(secrets, f'the {SECRET_NAME} secret is no longer managed by this stack')
        ids = {secrets[0]['values'].get(k) for k in ('id', 'arn')} - {None}
        versions = [r for r in self.of_type('aws_secretsmanager_secret_version')
                    if r.get('values', {}).get('secret_id') in ids]
        self.assertTrue(versions, f'no aws_secretsmanager_secret_version writes {SECRET_NAME}')
        for v in versions:
            values = v.get('values', {})
            self.assertIn(values.get('secret_string'), (None, ''),
                          f'{v["address"]}.secret_string is stored in state')
            self.assertIsNotNone(values.get('secret_string_wo_version'),
                                 f'{v["address"]} does not use secret_string_wo')

    def test_app_secret_has_what_the_service_reads(self):
        data, _ = self.password()
        dbs = self.of_type('aws_db_instance')
        db = dbs[0]['values'] if dbs else {}
        missing = {'username', 'password', 'host', 'port', 'dbname'} - set(data)
        self.assertFalse(missing, f'{SECRET_NAME} is missing keys {sorted(missing)}')
        self.assertEqual(data['host'], DB_HOST, 'host is not the instance address')
        self.assertEqual(str(data['port']), '5432', 'port is not the instance port')
        self.assertEqual(data['username'], db.get('username'), 'username is not the master username')
        self.assertEqual(data['dbname'], db.get('db_name'), 'dbname is not the database name')

    def test_password_is_valid_for_rds_postgres(self):
        _, pw = self.password()
        self.assertTrue(8 <= len(pw) <= 128, f'RDS for PostgreSQL needs 8 to 128 characters, got {len(pw)}')
        bad = sorted(set(pw) & RDS_FORBIDDEN)
        self.assertFalse(bad, f'RDS rejects master passwords containing {bad}')
        for b in self.blocks:
            if b.kind != 'ephemeral' or not b.labels:
                continue
            if b.labels[0] == 'random_password':
                special = tv.literal(b.attrs.get('special'))
                override = tv.literal(b.attrs.get('override_special'))
                if special is False:
                    continue
                chars = override if isinstance(override, str) else (
                    RANDOM_DEFAULT_SPECIAL if 'override_special' not in b.attrs else '')
                self.assertFalse(
                    set(chars) & RDS_FORBIDDEN,
                    f'{b.address} can generate {sorted(set(chars) & RDS_FORBIDDEN)}, which RDS rejects '
                    '(the default special set includes "@")',
                )
            if b.labels[0] == 'aws_secretsmanager_random_password':
                if tv.literal(b.attrs.get('exclude_punctuation')) is True:
                    continue
                excluded = tv.literal(b.attrs.get('exclude_characters'))
                if 'exclude_characters' in b.attrs and not isinstance(excluded, str):
                    continue  # not a literal; the runtime check above still applies
                self.assertFalse(
                    RDS_FORBIDDEN - set(excluded or ''),
                    f'{b.address} can generate {sorted(RDS_FORBIDDEN - set(excluded or ""))}, '
                    'which RDS rejects',
                )

    def test_password_appears_nowhere_in_state(self):
        _, pw = self.password()
        where = [r['address'] for r in self.resources if pw in json.dumps(r)]
        if pw in json.dumps(self.state.get('root_module', {})) or where:
            self.fail(f'the generated password is stored in the state ({", ".join(where) or "outputs"})')

    def test_db_and_secret_share_one_password_source(self):
        self.require_apply()
        generators = [b for b in self.blocks if b.kind == 'ephemeral' and b.labels[:1]
                      and b.labels[0] in GENERATORS]
        self.assertLessEqual(
            len(generators), 1,
            f'{[g.address for g in generators]}: more than one password generator, so the DB and '
            f'{SECRET_NAME} can end up with different passwords',
        )


if __name__ == '__main__':
    unittest.main()
